private static func parseNumber(token: String): Int64 {
    let bytes = token.toArray()
    var index: Int64 = 0
    var negative = false
    if (bytes[0] == 43 || bytes[0] == 45) {
        negative = bytes[0] == 45
        index = 1
    }
    if (index == bytes.size) { throw IllegalArgumentException("invalid token") }
    var value: Int64 = 0
    let limit: Int64 = if (negative) { 2147483648 } else { 2147483647 }
    while (index < bytes.size) {
        let digit = bytes[index]
        if (digit < 48 || digit > 57) { throw IllegalArgumentException("invalid token") }
        value = value * 10 + Int64(digit - 48)
        if (value > limit) { throw IllegalArgumentException("out of int32 range") }
        index++
    }
    return if (negative) { -value } else { value }
}

func testSignedNumbers(): Unit {
    let actual = InstructionParser.parse("-7 +8 0 007")
    expectArray(actual, [-7, 8, 0, 7])
}

func testInt32Boundaries(): Unit {
    let actual = InstructionParser.parse("-2147483648 2147483647")
    expectArray(actual, [-2147483648, 2147483647])
}

private func expectArray(actual: Array<Int64>, expected: Array<Int64>): Unit {
    @Assert(actual.size, expected.size)
    for (i in 0..expected.size) { @Expect(actual[i], expected[i]) }
}
